using System;using System.Collections.Generic;using Beast.Claw.Attributes;using Beast.Claw.Collection;using Beast.Claw.Reflection;using Unity.Mathematics;namespace Beast.Claw.Debug{    [DomainInitialize]    public static class BDebug    {        public static IReadOnlyDictionary<string, DebugTrackStorage> TrackStorages => _trackStorages;                private static readonly Dictionary<string, DebugTrackStorage> _trackStorages;        static BDebug()        {            try            {                _trackStorages = new Dictionary<string, DebugTrackStorage>();            }            catch (Exception e)            {                _logException(e);            }        }        public static void ClearTrackStorage()        {            _trackStorages.Clear();        }                public static void Track<T>(T owner, string id, int value)        {            _getOrCreateStorage(owner).Write(id, value);        }                public static void Track<T>(T owner, string id, float value)        {            _getOrCreateStorage(owner).Write(id, value);        }        public static void Track<T>(T owner, string id, float2 value)        {            _getOrCreateStorage(owner).Write(id, value);        }                public static void Track<T>(T owner, string id, float3 value)        {            _getOrCreateStorage(owner).Write(id, value);        }                public static void Track<T>(T owner, string id, float4 value)        {            _getOrCreateStorage(owner).Write(id, value);        }                public static void Track<T>(T owner, string id, string value)        {            _getOrCreateStorage(owner).Write(id, value);        }                public static void LogInfo<T>(T owner, string message, object context = null)        {            _logInfo(TypeStorage<T>.FullName + ": " + message, context);        }                public static void LogError<T>(T owner, string message, object context = null)        {            _logError(TypeStorage<T>.FullName + ": " + message, context);        }        public static void LogWarning<T>(T owner, string message, object context = null)        {            _logWarning(TypeStorage<T>.FullName + ": " + message, context);        }        public static void LogException<T>(T owner, Exception e, string message)        {            _logError(TypeStorage<T>.FullName + ": " + message, null);            _logException(e);        }                public static void StaticLogError(string message, object context = null)        {            _logError(message, context);        }        public static void StaticLogInfo(string message, object context = null)        {            _logInfo(message, context);        }        public static void StaticLogException(Exception e)        {            _logException(e);        }        private static void _logInfo(string message, object context)        {            if (context is UnityEngine.Object unityObject)            {                UnityEngine.Debug.Log(message, unityObject);                return;            }                        UnityEngine.Debug.Log(message);        }        private static void _logWarning(string message, object context)        {            if (context is UnityEngine.Object unityObject)            {                UnityEngine.Debug.LogWarning(message, unityObject);                return;            }                        UnityEngine.Debug.LogWarning(message);        }                private static void _logError(string message, object context)        {            if (context is UnityEngine.Object unityObject)            {                UnityEngine.Debug.LogError(message, unityObject);            }                        UnityEngine.Debug.LogError(message);        }        private static void _logException(Exception e)        {            UnityEngine.Debug.LogException(e);        }        private static DebugTrackStorage _getOrCreateStorage<TOwner>(TOwner owner)        {            string name = TypeStorage<TOwner>.FullName;            return _trackStorages.GetOrCreate(name);        }    }}